import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第十三章","description":"《正易心法》第十三章——坎兑二水，明须识破：坎为一阳陷阴中之乾水（气之液），兑为一阴浮阳上之坤水（形之散）；以井卦卦变、《月令》物候、炼丹井、医经四重验证。","frontmatter":{"title":"正易心法·第十三章","description":"《正易心法》第十三章——坎兑二水，明须识破：坎为一阳陷阴中之乾水（气之液），兑为一阴浮阳上之坤水（形之散）；以井卦卦变、《月令》物候、炼丹井、医经四重验证。","category":"guide","aliases":["正易心法第十三章","坎兑二水","坎乾水兑坤水"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-13.md","filePath":"yijing/zheng-yi-xin-fa/chapter-13.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-13.md"},k=p({...c,setup(u){const i=[{id:"z13-01",label:"一、明须识破",showLabel:!0,sentences:[["坎兑二水，明须",{text:"识破",glossary:"shipo"},"。坎",{text:"润",glossary:"run"},"兑",{text:"说",glossary:"yue"},"，理自不同。"]],note:["坎与兑同为水，必须看清楚、辨明白：坎是润泽，兑是喜悦散布，道理本自不同。（这是第十二章「八字通用原则」的第一个具体应用——两者都与「水」有关，但卦画结构不同，**必须从卦画结构区分，不能只看「水」这个文字标签**。）"]},{id:"z13-02",label:"二、坎乾水兑坤水",showLabel:!0,sentences:[["坎，",{text:"乾水",glossary:"qianshui"},"也，气也，若井是也。兑，",{text:"坤水",glossary:"kunshui"},"也，形也，今雨是也。"]],note:["坎，是乾阳之水，是气，就像井水一样；兑，是坤阴之水，是形，就像雨水一样。（这极其反直觉：直觉上水是阴性的，怎么坎水反而是「乾水」？麻衣的逻辑是——**坎的卦画是一阳陷于二阴之中 = 乾阳被坤阴包裹 = 外表是阴（水的形质），内里是阳（乾气的潜藏）**。兑的卦画是一阴浮于二阳之上 = 坤阴浮在乾阳之上，本质是坤阴的外散。）"]},{id:"z13-03",label:"三、坎以气潜行",showLabel:!0,sentences:[["一阳中陷为二阴为坎，坎以气潜行于万物之中，为受命之根本，故曰：润万物者莫润乎水。盖润，液也，气之液也。"]],note:["坎卦是一阳陷入二阴之中——坎水以气的形式潜行于万物之中，是万物受命的根本。所以说「润泽万物，没有比水更能润泽的」；这个「润」，是液化的意思，是气凝结为液的状态。（方向：**由外向内、由上向下，潜行渗透**——象如井水渗入土壤，滋养根系。）"]},{id:"z13-04",label:"四、兑以形普施",showLabel:!0,sentences:[["一阴上彻于二阳为兑，兑以形普施于万物之上，为发生之利泽，故曰：说万物者莫说乎泽。盖说，散也，形之散也。"]],note:["兑卦是一阴上彻于二阳之上——兑水以形质的方式普遍施与万物之上，是促进万物发生的恩泽。所以说「使万物喜悦，没有比泽更能使万物喜悦的」；这个「说（悦）」，是散布的意思，是形质散布施与的状态。（方向：**由内向外、由上向下，普遍散布**——象如雨水从天而降，普施大地。注意「说」在此通「悦」。）"]},{id:"z13-05",label:"五、依文解义不知落处",showLabel:!0,sentences:[["坎、兑二水，其理昭昭如此。学者",{text:"依文解义",glossary:"yiwenJieyi"},"，不知",{text:"落处",glossary:"luochu"},"，其能得实用乎？自汉诸儒不得其说，故真人发其端。"]],note:["坎、兑二水，道理如此昭然。学者只依文字解义、不知落处，怎能得到实际的用处？（「真人发其端」是麻衣少见的自我指认。这一句与第一章「学者不知落处，则所谓玩占者，亦虚语耳」完全同调——**「落处」在第一章是总纲，在本章是具体案例**：坎水的落处是乾阳潜藏于阴中（井水、肾水、地下水），兑水的落处是坤阴散布于阳上（雨水、泽水、地表水）。）"]},{id:"z13-06",label:"六、井卦与月令",showLabel:!0,sentences:[["又论，且以井卦观之，本来泰卦初爻易五，是为井，则知一阳升而为坎水也。故《月令》云：“仲冬，水泉动，仲冬一阳生。”至仲秋，乃云：“杀气侵盛，阳气日衰，水始涸。”信乎坎之为乾水也！"]],note:["再论：以井卦来看，井卦本来是泰卦的初爻与五爻互换而成，由此可知一阳上升即为坎水。所以《月令》说「仲冬，水泉涌动——仲冬一阳初生」；到了仲秋，又说「杀气渐盛，阳气日衰，水开始干涸」。这正验证了坎水是乾阳之水！（**水的枯荣跟随阳气的消长**——仲冬一阳生则水泉动，仲秋阳气衰则水始涸。这是四重证据中的第二重。）"]},{id:"z13-07",label:"七、炼丹井与医经",showLabel:!0,sentences:[["道家有",{text:"炼丹井",glossary:"liandanJing"},"，海外女国无男，",{text:"窥井即生",glossary:"kuijingJisheng"},"。《医经》：“无子妇人，男服口脂，循井即孕。”其为乾阳，皆可明验。若曰：天降时雨，山川出云，又曰：地气上为云，天气下为雨，此兑之所以为坤水也。"]],note:["道家有炼丹井，海外女国无男，女子窥井即可受孕；《医经》说：「无子的妇人，男子服口脂，循井即可受孕。」这些都是坎水含乾阳的明证。（这两条是「民俗与医经」层面的旁证——看似荒诞，指向的都是同一件事：**井水含乾阳，故有生育之力**。最后一句转到兑：「天降时雨，山川出云」「地气上为云，天气下为雨」，正是兑水作为坤阴之水的道理——**雨水从上而降，是坤阴之形的外散**。至此四重验证完备：卦理、物候、卦变、民俗医经，坎兑二水各归其位。）"]}],o=[{id:"shipo",term:"识破",pinyin:"shí pò",meaning:"看穿、辨清。必须分清坎兑二水的本质差异。"},{id:"run",term:"润",pinyin:"rùn",meaning:"滋润渗透。麻衣解作「液也，气之液」——气凝为液，向内渗透，是坎水之德。"},{id:"yue",term:"说",pinyin:"yuè",meaning:"通「悦」，此处解作「散」——「形之散」，向外散布施与，是兑水之德。"},{id:"qianshui",term:"乾水",pinyin:"qián shuǐ",meaning:"属于乾阳系统的水。坎为坤体藏乾阳，故水中有阳气，如井水、地下水。"},{id:"kunshui",term:"坤水",pinyin:"kūn shuǐ",meaning:"属于坤阴系统的水。兑为乾体藏坤阴，故水是纯阴形质，如雨水。"},{id:"yiwenJieyi",term:"依文解义",pinyin:"yī wén jiě yì",meaning:"只从文字表面理解。麻衣批评不看卦画、只看文字的学者。"},{id:"luochu",term:"落处",pinyin:"luò chù",meaning:"卦象的具体对应位置。第一章核心概念，本章再次点出。"},{id:"liandanJing",term:"炼丹井",pinyin:"liàn dān jǐng",meaning:"道家用井水炼丹，所取为井水中所含的乾阳。"},{id:"kuijingJisheng",term:"窥井即生",pinyin:"kuī jǐng jí shēng",meaning:"望入井中即可受孕。传说的海外女国，谓井水含乾阳，有生育之力。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第十三章" tabindex="-1">正易心法·第十三章 <a class="header-anchor" href="#正易心法·第十三章" aria-label="Permalink to &quot;正易心法·第十三章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是第十二章「八字通用原则」的<strong>第一个具体应用</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第十二章（方法论）：八字不是标签，是结构原则，要从卦画推导</span></span>
<span class="line"><span>第十三章（应用一）：以坎（陷）和兑（说）为例</span></span>
<span class="line"><span>  两者都与「水」有关，但卦画结构不同 → 坎水 ≠ 兑水</span></span>
<span class="line"><span>  必须从卦画结构区分，不能只看「水」这个文字标签</span></span></code></pre></div><p><strong>核心命题</strong>：同样叫「水」，<strong>坎水是乾阳之气（内藏、渗透、生命根本），兑水是坤阴之形（外散、施与、发生利泽）</strong>——不识破这个区别，就是「依文解义，不知落处」。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>坎为什么是「乾水」？</strong> 这是本章最反直觉的地方：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坎的卦画 = 一阳陷于二阴中 = 乾阳被坤阴包裹</span></span>
<span class="line"><span>        = 外表是阴（水的形质），内里是阳（乾气的潜藏）</span></span>
<span class="line"><span>        = 乾阳被液化、被包裹的状态 = 「气之液」</span></span></code></pre></div><p><strong>与第七章完全吻合</strong>：「坎得乾中爻，故月自天之中而运」——<strong>月是阴包阳，井水是阴包阳，人体的肾水也是阴包阳（内丹的核心）。</strong></p><p><strong>兑为什么是「坤水」？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>兑的卦画 = 一阴浮于二阳之上 = 坤阴浮在乾阳之上</span></span>
<span class="line"><span>        = 阴形浮于阳气之上，向外散布 = 「形之散」</span></span>
<span class="line"><span>        = 雨水（从天而降，普施大地）</span></span></code></pre></div><p><strong>四重验证</strong>（麻衣给出三个层次、四个证据）：</p><table tabindex="0"><thead><tr><th>层次</th><th>证据</th></tr></thead><tbody><tr><td><strong>卦理</strong></td><td>坎＝一阳陷于二阴中＝乾水</td></tr><tr><td><strong>物候</strong></td><td>《月令》：仲冬一阳生则水泉动，仲秋阳气衰则水始涸</td></tr><tr><td><strong>卦变</strong></td><td>井卦是泰卦初爻与五爻互换——一阳上升即坎水</td></tr><tr><td><strong>民俗／医经</strong></td><td>道家炼丹井；海外女国窥井即生；《医经》循井即孕</td></tr></tbody></table><p><strong>内丹的深层含义</strong>——本章的「道家炼丹井」不是随意举例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内丹核心公式：取坎填离</span></span>
<span class="line"><span>  = 取坎中之阳（坎水中的乾阳）</span></span>
<span class="line"><span>  = 填入离中之阴（离火中的坤阴）</span></span>
<span class="line"><span>  = 坎离交媾 → 恢复乾坤纯体</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这里说的「坎水」不是普通的水，而是人体内的「肾水」（含真阳）</span></span>
<span class="line"><span>= 乾阳潜藏于肾水之中</span></span>
<span class="line"><span>= 与井水含乾阳是同一个道理</span></span></code></pre></div><p>第十一章说「破体炼之，纯体乃成」——<strong>第十三章给出了「炼」的具体材料：坎水中的乾阳，就是炼丹的原料。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把坎☵与兑☱的卦画画出来，看<strong>阳爻在哪个位置</strong>；</li><li>再读「气之液」与「形之散」——<strong>这两个词是本章的钥匙</strong>；</li><li>最后看四重验证：它不只是「说得通」，而是<strong>层层印证</strong>。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>识破二水</strong>：同名为水，本质不同。</li><li><strong>坎＝乾水</strong>：气之液，如井水，生命根本。</li><li><strong>兑＝坤水</strong>：形之散，如雨水，发生利泽。</li><li><strong>依文解义</strong>：不知落处，则无实用。</li><li><strong>井卦与月令</strong>：水之枯荣随阳气消长。</li><li><strong>炼丹井</strong>：取坎中之阳——内丹的原料。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(r,{colophon:"坎乾水 · 兑坤水 · 气之液 · 形之散",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十三章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（「说」通「悦」、「曰为天之气」之「曰」等），不作统一。原文末段「凡此卦画，皆所以写天地万物之理于目前」一句据底本属本章末，本页依底本分段。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"坎为乾水",pinyin:["kǎn","qián"],meaning:"坎是一阳陷于二阴中＝乾阳被坤阴包裹，外表是水（阴），内里是阳（乾气）——「气之液」，如井水、地下水、肾水。"},{term:"兑为坤水",pinyin:["duì","kūn"],meaning:"兑是一阴浮于二阳上＝坤阴浮在乾阳之上，是阴形外散——「形之散」，如雨水。"},{term:"气之液 · 形之散",pinyin:["qì","zhī"],meaning:"润＝气之液（向内渗透）；说（悦）＝形之散（向外散布）。这是坎兑二水最精要的两个定义。"},{term:"井卦卦变",pinyin:["jǐng","guà"],meaning:"井卦是泰卦初爻与五爻互换而成——一阳上升被坤阴包裹即坎，验证「坎水是乾阳之气上升」。"},{term:"月令物候",pinyin:["yuè","lìng"],meaning:"仲冬一阳生则「水泉动」，仲秋阳气衰则「水始涸」——水的枯荣跟随阳气消长。"},{term:"炼丹井",pinyin:["liàn","dān"],meaning:"道家用井水炼丹，所取为井水中的乾阳。内丹「取坎填离」的原料，与此同理。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是第十二章「从卦画结构推导义理」的第一个具体应用：<strong>辨清坎兑二水</strong>。</p><p><strong>核心命题</strong>：同名为水，<strong>坎水是乾阳之气（内藏、渗透、生命根本），兑水是坤阴之形（外散、施与、发生利泽）</strong>——不识破这个区别，就是「依文解义，不知落处」。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>坎为什么是「乾水」？</strong> 直觉上水是阴性的，但：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坎的卦画 = 一阳陷于二阴中 = 乾阳被坤阴包裹</span></span>
<span class="line"><span>        = 外表是阴（水的形质），内里是阳（乾气的潜藏）</span></span>
<span class="line"><span>        = 「气之液」</span></span></code></pre></div><p><strong>四重验证</strong>：</p><table tabindex="0"><thead><tr><th>层次</th><th>证据</th></tr></thead><tbody><tr><td>卦理</td><td>坎＝一阳陷于二阴中</td></tr><tr><td>物候</td><td>《月令》：仲冬水泉动（一阳生），仲秋水始涸（阳气衰）</td></tr><tr><td>卦变</td><td>井卦是泰卦初五互换——一阳上升为坎水</td></tr><tr><td>民俗／医经</td><td>炼丹井、女国窥井即生、循井即孕</td></tr></tbody></table><p><strong>内丹的深层含义</strong>：内丹核心公式「取坎填离」——取坎中之阳（乾阳），填入离中之阴（坤阴），坎离合而复原为乾坤。<strong>第十一章说「破体炼之，纯体乃成」，第十三章给出了「炼」的具体材料。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>画坎☵与兑☱，看阳爻的位置；</li><li>记住两个词：「<strong>气之液</strong>」「<strong>形之散</strong>」；</li><li>顺着钩子想：<strong>人体里的津液，哪些是坎水，哪些是兑水？</strong> 我的推法：<strong>内藏的、滋养根本的（肾水、骨髓、津液）是坎水（含真阳）；外散的、发散于表的（汗、涕、泪）是兑水（纯阴之形）。</strong> 所以「汗为心之液」——汗是心（火）向外发散出来的兑水，所以出汗多会伤心；而肾水（坎）则宜藏不宜泄。<strong>这正是第十四章「体用之辨」在人体上的落处。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>坎与兑同为水，必须看清楚、辨明白：坎是润泽，兑是喜悦散布，道理本自不同。</p><p>坎，是乾阳之水，是气，就像井水一样。兑，是坤阴之水，是形，就像雨水一样。</p><p>坎卦是一阳陷入二阴之中——坎水以气的形式潜行于万物之中，是万物受命的根本。所以说「润泽万物，没有比水更能润泽的」；这个「润」，是液化的意思，是气凝结为液的状态。</p><p>兑卦是一阴上彻于二阳之上——兑水以形质的方式普遍施与万物之上，是促进万物发生的恩泽。所以说「使万物喜悦，没有比泽更能使万物喜悦的」；这个「说（悦）」，是散布的意思，是形质散布施与的状态。</p><p>坎、兑二水，道理如此昭然。学者只依文字解义、不知落处，怎能得到实际的用处？自汉代诸儒不得此说，故真人在此开启端绪。</p><p>再论：以井卦来看，井卦本来是泰卦的初爻与五爻互换而成，由此可知一阳上升即为坎水。《月令》说「仲冬，水泉涌动——仲冬一阳初生」；到了仲秋，又说「杀气渐盛，阳气日衰，水开始干涸」。这正验证了坎水是乾阳之水！</p><p>道家有炼丹井，海外女国无男，女子窥井即可受孕。《医经》说：「无子的妇人，男子服口脂，循井即可受孕。」这些都是坎水含乾阳的明证。至于说「天降时雨，山川出云」，又说「地气上为云，天气下为雨」——这正是兑水作为坤阴之水的道理。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十三章做了一件很硬的事——<strong>它用卦画结构，把「水」这个词劈成了两半：一半是气（井水，乾阳），一半是形（雨水，坤阴）。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「同名为水」的陷阱</strong>——这大概是全书最好的一个例子：<strong>两个东西名字一样，本质却相反。</strong> 我生活里有多少「同名为水」的东西？名字相同，落处不同。</li><li><strong>「气之液」与「形之散」</strong>——<strong>向内的是气，向外的是形；藏的是真阳，散的是阴形。</strong> 这两个词可以直接拿来检验很多事：我做的这件事，是「气之液」还是「形之散」？是滋养根本，还是普施于表？</li><li><strong>「学者依文解义，不知落处，其能得实用乎？」</strong>——这句话与第一章几乎同调。<strong>「实用」是麻衣的标准：不是说得漂亮，是能不能用。</strong></li><li><strong>四重验证的态度</strong>——卦理、物候、卦变、民俗医经。<strong>这四层不是「举例」，是四个不同角度的印证。</strong> 麻衣不满足于「说得通」，他要「到处都对」。</li><li><strong>坎离与「炼」</strong>——第十一章说的「炼」，本章给出了材料：<strong>坎水中的乾阳。</strong> 内丹「取坎填离」不是玄谈，它的原料就在这个卦画结构里。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>人体的津液，哪些是坎水，哪些是兑水？</strong> 我的推法：<strong>内藏滋养的（肾水、骨髓）是坎水（含真阳）；外散发散的（汗、涕、泪）是兑水（纯阴之形）</strong>。这正好解释中医「汗为心之液」（汗由心火外散，故多汗伤心）与「肾主藏」（坎宜藏不宜泄）——<strong>不是巧合，是同一个卦画逻辑。</strong> 这与第十四章的「体用之辨」正好接上。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「不知落处，则玩占亦虚语」（本章同调）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-07">第七章 · 观于卦脉</a> — 「坎得乾中爻，故月自天之中而运」（本章深化）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-11">第十一章 · 偏陂反侧</a> — 「破体炼之」（本章给出「炼」的材料：坎中之乾阳）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-12">第十二章 · 八字非标签</a> — 从卦画结构推导义理（本章是第一个应用）</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「润万物者莫润乎水，说万物者莫说乎泽」：麻衣给这两句补上了本质定义</li></ul>`,26))])}}});export{m as __pageData,k as default};
